function ContactForm() {
  const [sent, setSent] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [messageLen, setMessageLen] = useState(0);

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError(null);
    const fd = new FormData(e.currentTarget);
    const name = String(fd.get("name") ?? "").trim();
    const phone = String(fd.get("phone") ?? "").trim();
    const message = String(fd.get("message") ?? "").trim();

    if (!name) return setError("Informe seu nome.");
    if (!phone) return setError("Informe seu WhatsApp.");
    if (!message) return setError("Conte rapidamente o que sua IA faz hoje.");
    if (message.length > 1000) return setError("Mensagem muito longa. Máximo de 1000 caracteres.");

    setLoading(true);
    try {
      await submitLead({
        phone,
        name,
        email: String(fd.get("email") ?? "") || null,
        company: String(fd.get("company") ?? "") || null,
        message,
        attribution: collectAttribution(),
      });
      setSent(true);
    } catch (err) {
      const msg = err instanceof Error ? err.message : "Não foi possível enviar. Tente novamente.";
      setError(msg.replace(/^Error:\s*/i, ""));
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="rounded-[34px] border border-white/10 bg-white p-5 text-[#0D0D0D] shadow-[0_24px_80px_rgba(0,0,0,0.18)] sm:p-7">
      <div className="mb-6 flex items-start justify-between gap-4">
        <div>
          <p className="text-xs font-bold uppercase tracking-[0.18em] text-[#FF5722]">Diagnóstico gratuito</p>
          <h3 className="mt-2 text-2xl font-bold tracking-[-0.04em]">Comece em 60 segundos</h3>
          <p className="mt-2 text-sm leading-6 text-[#5C5C5C]">Sem compromisso. Retorno em até 24h.</p>
        </div>
        <span className="grid h-12 w-12 place-items-center rounded-2xl bg-[#0D0D0D] text-white">→</span>
      </div>

      {sent ? (
        <div className="py-16 text-center">
          <div className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-emerald-100 text-2xl text-emerald-700">✓</div>
          <p className="mt-5 text-2xl font-bold tracking-[-0.04em]">Recebido.</p>
          <p className="mt-2 text-sm text-[#5C5C5C]">Entraremos em contato em até 24h.</p>
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid gap-4 sm:grid-cols-2">
            <Field label="Nome *" name="name" type="text" placeholder="Seu nome" required />
            <Field label="Empresa" name="company" type="text" placeholder="Nome da empresa" />
          </div>
          <Field label="E-mail corporativo" name="email" type="email" placeholder="voce@empresa.com" />
          <Field label="WhatsApp *" name="phone" type="tel" placeholder="+55 (11) 99999-9999" required />
          <div>
            <div className="mb-2 flex items-center justify-between">
              <label htmlFor="message" className="text-xs font-bold text-[#0D0D0D]/70">O que sua IA faz hoje? *</label>
              <span className={`text-[11px] ${messageLen > 1000 ? "text-red-600" : "text-[#5C5C5C]"}`}>{messageLen}/1000</span>
            </div>
            <textarea
              id="message"
              name="message"
              rows={4}
              maxLength={1000}
              onChange={(e) => setMessageLen(e.target.value.length)}
              placeholder="Ex.: usamos IA no atendimento, mas ainda não medimos qualidade, custo por conversa ou falhas por fluxo."
              required
              className="input min-h-[128px] resize-none"
            />
          </div>
          {error && <p className="rounded-2xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">{error}</p>}
          <button type="submit" disabled={loading} className="w-full rounded-[20px] bg-[#0D0D0D] px-6 py-4 text-sm font-bold text-white transition hover:-translate-y-0.5 hover:bg-[#FF5722] disabled:cursor-not-allowed disabled:opacity-70">
            {loading ? "Enviando…" : "Solicitar análise"}
          </button>
          <p className="text-center text-[11px] leading-5 text-[#5C5C5C]">Ao enviar, você concorda em ser contatado sobre o diagnóstico.</p>
        </form>
      )}
    </div>
  );
}

function Field({ label, name, type, placeholder, required }: { label: string; name: string; type: string; placeholder?: string; required?: boolean }) {
  return (
    <div>
      <label htmlFor={name} className="mb-2 block text-xs font-bold text-[#0D0D0D]/70">{label}</label>
      <input id={name} name={name} type={type} placeholder={placeholder} required={required} className="input" />
    </div>
  );
}

