function DotLottie({ src, label, className = "" }: { src: string; label: string; className?: string }) {
  useEffect(() => {
    if (typeof document === "undefined") return;
    if (document.getElementById("dotlottie-wc-script")) return;
    const script = document.createElement("script");
    script.id = "dotlottie-wc-script";
    script.src = "https://unpkg.com/@lottiefiles/dotlottie-wc@0.9.14/dist/dotlottie-wc.js";
    script.type = "module";
    document.head.appendChild(script);
  }, []);

  return (
    <div className={`h-full w-full ${className}`} role="img" aria-label={label}>
      {createElement("dotlottie-wc", {
        src,
        autoplay: true,
        loop: true,
        style: { width: "100%", height: "100%" } as CSSProperties,
      })}
    </div>
  );
}

function CountUp({ to, from = 0, prefix = "", suffix = "", duration = 1200 }: { to: number; from?: number; prefix?: string; suffix?: string; duration?: number }) {
  const [ref, visible] = useInView<HTMLSpanElement>();
  const [value, setValue] = useState(from);

  useEffect(() => {
    if (!visible) return;
    let frame = 0;
    const start = performance.now();
    const tick = (now: number) => {
      const progress = Math.min((now - start) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setValue(from + (to - from) * eased);
      if (progress < 1) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [duration, from, to, visible]);

  const formatted = Math.round(value).toLocaleString("pt-BR");
  return <span ref={ref}>{prefix}{formatted}{suffix}</span>;
}

function TypewriterText({ text, speed = 28, className = "" }: { text: string; speed?: number; className?: string }) {
  const [ref, visible] = useInView<HTMLSpanElement>();
  const [display, setDisplay] = useState("");

  useEffect(() => {
    if (!visible) return;
    let index = 0;
    const reduced = typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduced) {
      setDisplay(text);
      return;
    }
    const id = window.setInterval(() => {
      index += 1;
      setDisplay(text.slice(0, index));
      if (index >= text.length) window.clearInterval(id);
    }, speed);
    return () => window.clearInterval(id);
  }, [speed, text, visible]);

  return (
    <span ref={ref} className={`typewriter ${className}`}>
      {display}
      {visible && display.length < text.length ? <span className="cursor">|</span> : null}
    </span>
  );
}

function Reveal({ children, delay = 0 }: { children: ReactNode; delay?: number }) {
  const [ref, visible] = useInView<HTMLDivElement>();
  return (
    <div ref={ref} className={`reveal ${visible ? "is-visible" : ""}`} style={{ transitionDelay: `${delay}ms` }}>
      {children}
    </div>
  );
}

function useInView<T extends HTMLElement>() {
  const ref = useRef<T | null>(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    if (!ref.current || visible) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.22, rootMargin: "0px 0px -8% 0px" },
    );
    observer.observe(ref.current);
    return () => observer.disconnect();
  }, [visible]);

  return [ref, visible] as const;
}

function Sparkline() {
  const points = "0,70 40,58 80,42 120,49 160,34 200,38 240,24 280,30 320,15";
  return (
    <svg viewBox="0 0 320 92" className="h-28 w-full overflow-visible">
      <defs>
        <linearGradient id="line" x1="0" x2="1">
          <stop stopColor="#FF5722" />
          <stop offset="1" stopColor="#16A34A" />
        </linearGradient>
      </defs>
      {[20, 45, 70].map((y) => <line key={y} x1="0" x2="320" y1={y} y2={y} stroke="white" strokeOpacity="0.08" />)}
      <polyline points={points} fill="none" stroke="url(#line)" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round" />
      <polyline points={`${points} 320,92 0,92`} fill="url(#line)" opacity="0.13" />
      {points.split(" ").map((point) => {
        const [x, y] = point.split(",");
        return <circle key={point} cx={x} cy={y} r="4" fill="white" opacity="0.9" />;
      })}
    </svg>
  );
}

